"""Async Ollama client for VEX corpus processing."""

import json
from pathlib import Path
from typing import Any

import httpx
import yaml
from pydantic import BaseModel

from .models import TaskResult, TaskStatus


class ModelConfig(BaseModel):
    """Configuration for a model tier."""

    primary: str
    fallbacks: list[str] = []
    config: dict[str, Any] = {}


class OllamaClient:
    """Async client for Ollama API with VEX corpus processing support."""

    def __init__(
        self,
        base_url: str = "http://localhost:11434",
        config_path: Path | None = None,
    ):
        self.base_url = base_url.rstrip("/")
        self.config = self._load_config(config_path)
        self._blueprint: str | None = None

    def _load_config(self, config_path: Path | None) -> dict[str, Any]:
        """Load configuration from YAML file."""
        if config_path is None:
            config_path = Path(__file__).parent.parent.parent / "config" / "models.yaml"

        if config_path.exists():
            with open(config_path) as f:
                return yaml.safe_load(f)
        return {}

    def load_blueprint(self, blueprint_path: Path | None = None) -> str:
        """Load the VEX processing blueprint as system prompt."""
        if blueprint_path is None:
            blueprint_path = (
                Path(__file__).parent.parent.parent
                / "blueprints"
                / "OLLAMA_PROCESSING_BLUEPRINT.md"
            )

        if blueprint_path.exists():
            self._blueprint = blueprint_path.read_text(encoding="utf-8")
        return self._blueprint or ""

    @property
    def blueprint(self) -> str:
        """Get the loaded blueprint, loading if necessary."""
        if self._blueprint is None:
            self.load_blueprint()
        return self._blueprint or ""

    def get_model_for_tier(self, tier: int) -> ModelConfig:
        """Get model configuration for the specified tier."""
        tier_key = f"tier{tier}"
        tier_config = self.config.get("models", {}).get(tier_key, {})
        return ModelConfig(
            primary=tier_config.get("primary", "nemotron-mini:latest"),
            fallbacks=tier_config.get("fallbacks", []),
            config=tier_config.get("config", {}),
        )

    async def health_check(self) -> dict[str, Any]:
        """Check Ollama server health and available models."""
        async with httpx.AsyncClient() as client:
            try:
                response = await client.get(f"{self.base_url}/api/tags", timeout=10.0)
                response.raise_for_status()
                data = response.json()

                models = data.get("models", [])
                available = {m["name"].split(":")[0] for m in models}

                required = {"nemotron-mini", "nemotron"}
                missing = required - available

                return {
                    "status": "healthy" if not missing else "degraded",
                    "available_models": sorted(available),
                    "missing_models": sorted(missing),
                    "model_count": len(models),
                }
            except httpx.RequestError as e:
                return {
                    "status": "offline",
                    "error": str(e),
                    "available_models": [],
                    "missing_models": [],
                }

    async def generate(
        self,
        model: str,
        prompt: str,
        system: str | None = None,
        options: dict[str, Any] | None = None,
        timeout: float = 60.0,
    ) -> dict[str, Any]:
        """Send a generate request to Ollama."""
        payload: dict[str, Any] = {
            "model": model,
            "prompt": prompt,
            "stream": False,
        }

        if system:
            payload["system"] = system

        if options:
            payload["options"] = options
            if "format" in options:
                payload["format"] = options.pop("format")

        async with httpx.AsyncClient() as client:
            response = await client.post(
                f"{self.base_url}/api/generate",
                json=payload,
                timeout=timeout,
            )
            response.raise_for_status()
            return response.json()

    async def process_task(
        self,
        task_type: str,
        input_data: dict[str, Any],
        task_id: str = "",
        model: str | None = None,
        use_focused_prompt: bool = True,
    ) -> TaskResult:
        """Process a VEX task using the appropriate model."""
        from .models import TIER1_TASKS, TIER2_TASKS, TaskType
        from .prompts import get_task_prompt

        # Determine tier and model
        try:
            task_enum = TaskType(task_type)
        except ValueError:
            return TaskResult(
                task_id=task_id,
                status=TaskStatus.ERROR,
                result={"error_type": "unknown_task", "error_message": f"Unknown task: {task_type}"},
            )

        if task_enum in TIER1_TASKS:
            tier = 1
        elif task_enum in TIER2_TASKS:
            tier = 2
        else:
            tier = 1

        model_config = self.get_model_for_tier(tier)
        selected_model = model or model_config.primary

        # Get task config - timeouts now properly configured in models.yaml
        task_config = self.config.get("tasks", {}).get(task_type, {})
        timeout = task_config.get("timeout_seconds", 60) * 1.0

        # Build prompt - include the code directly for better parsing
        code = input_data.get("code", "")
        prompt = f"Task ID: {task_id}\n\nVEX Code:\n```vex\n{code}\n```\n\nAnalyze this VEX code and respond with JSON."

        # Get system prompt - use focused prompt for better results with smaller models
        if use_focused_prompt:
            system = get_task_prompt(task_type) or self.blueprint
        else:
            system = self.blueprint

        # Build options from model config
        options = dict(model_config.config)

        models_to_try = [selected_model] + model_config.fallbacks

        for i, model_name in enumerate(models_to_try):
            try:
                response = await self.generate(
                    model=model_name,
                    prompt=prompt,
                    system=system,
                    options=options,
                    timeout=timeout,
                )

                result = self._parse_response(response, task_id)
                result.model_used = model_name
                if i > 0:
                    result.fallback_used = model_name
                return result

            except httpx.TimeoutException:
                if i < len(models_to_try) - 1:
                    continue
                return TaskResult(
                    task_id=task_id,
                    status=TaskStatus.ERROR,
                    result={"error_type": "timeout", "error_message": "All models timed out"},
                    model_used=model_name,
                )
            except httpx.HTTPStatusError as e:
                if i < len(models_to_try) - 1:
                    continue
                return TaskResult(
                    task_id=task_id,
                    status=TaskStatus.ERROR,
                    result={"error_type": "http_error", "error_message": str(e)},
                    model_used=model_name,
                )
            except Exception as e:
                if i < len(models_to_try) - 1:
                    continue
                return TaskResult(
                    task_id=task_id,
                    status=TaskStatus.ERROR,
                    result={"error_type": "unknown_error", "error_message": str(e)},
                    model_used=model_name,
                )

        return TaskResult(
            task_id=task_id,
            status=TaskStatus.ERROR,
            result={"error_type": "all_models_failed", "error_message": "No models available"},
        )

    def _parse_response(self, response: dict[str, Any], task_id: str) -> TaskResult:
        """Parse Ollama response into TaskResult."""
        content = response.get("response", "")

        # Handle JSON in markdown blocks
        if "```json" in content:
            content = content.split("```json")[1].split("```")[0]
        elif "```" in content:
            content = content.split("```")[1].split("```")[0]

        content = content.strip()

        try:
            parsed = json.loads(content)

            # Extract fields from parsed response
            status_str = parsed.get("status", "success")
            try:
                status = TaskStatus(status_str)
            except ValueError:
                status = TaskStatus.SUCCESS

            return TaskResult(
                task_id=parsed.get("task_id", task_id),
                status=status,
                result=parsed.get("result", parsed),
                confidence=float(parsed.get("confidence", 0.0)),
                processing_notes=parsed.get("processing_notes", ""),
            )

        except json.JSONDecodeError:
            return TaskResult(
                task_id=task_id,
                status=TaskStatus.ERROR,
                result={
                    "error_type": "parse_error",
                    "error_message": "Failed to parse JSON response",
                    "raw_response": content[:500],
                },
            )

    async def list_models(self) -> list[dict[str, Any]]:
        """List all available Ollama models."""
        async with httpx.AsyncClient() as client:
            response = await client.get(f"{self.base_url}/api/tags", timeout=10.0)
            response.raise_for_status()
            return response.json().get("models", [])

"""Task dispatcher with routing and batch processing for VEX corpus."""

import asyncio
from collections import Counter
from pathlib import Path
from typing import Any

from .client import OllamaClient
from .models import (
    BatchResult,
    TaskResult,
    TaskStatus,
    TaskType,
    TIER1_TASKS,
    TIER2_TASKS,
)


class TaskDispatcher:
    """Routes and dispatches VEX processing tasks to appropriate models."""

    def __init__(
        self,
        client: OllamaClient | None = None,
        config_path: Path | None = None,
    ):
        self.client = client or OllamaClient(config_path=config_path)
        self._config = self.client.config

    def get_tier(self, task_type: str | TaskType) -> int:
        """Determine which tier a task belongs to."""
        if isinstance(task_type, str):
            try:
                task_type = TaskType(task_type)
            except ValueError:
                return 1

        if task_type in TIER1_TASKS:
            return 1
        elif task_type in TIER2_TASKS:
            return 2
        return 1

    def get_model(self, task_type: str | TaskType) -> str:
        """Get the primary model for a task type."""
        tier = self.get_tier(task_type)
        return self.client.get_model_for_tier(tier).primary

    def should_use_consensus(self, task_type: str) -> bool:
        """Check if a task type requires consensus voting."""
        task_config = self._config.get("tasks", {}).get(task_type, {})
        return task_config.get("consensus", False)

    async def dispatch(
        self,
        task_type: str,
        input_data: dict[str, Any],
        task_id: str = "",
    ) -> TaskResult:
        """Dispatch a single task to the appropriate model."""
        if self.should_use_consensus(task_type):
            return await self.dispatch_with_consensus(task_type, input_data, task_id)
        return await self.client.process_task(task_type, input_data, task_id)

    async def dispatch_with_consensus(
        self,
        task_type: str,
        input_data: dict[str, Any],
        task_id: str = "",
    ) -> TaskResult:
        """Dispatch task to multiple models and use consensus voting."""
        tier = self.get_tier(task_type)
        model_config = self.client.get_model_for_tier(tier)

        # Get models to use for consensus
        models = [model_config.primary] + model_config.fallbacks[:2]

        # Run all models in parallel
        tasks = [
            self.client.process_task(task_type, input_data, task_id, model=m)
            for m in models
        ]
        results = await asyncio.gather(*tasks, return_exceptions=True)

        # Filter successful results
        valid_results: list[TaskResult] = []
        for r in results:
            if isinstance(r, TaskResult) and r.status == TaskStatus.SUCCESS:
                valid_results.append(r)

        if not valid_results:
            return TaskResult(
                task_id=task_id,
                status=TaskStatus.ERROR,
                result={"error_type": "consensus_failed", "error_message": "No valid results"},
            )

        # Extract vote key based on task type
        votes = []
        for r in valid_results:
            vote = self._extract_vote_key(task_type, r)
            if vote is not None:
                votes.append((vote, r))

        if not votes:
            return valid_results[0]

        # Count votes
        vote_counts = Counter(v[0] for v in votes)
        winner, count = vote_counts.most_common(1)[0]
        consensus_score = count / len(models)

        # Find best matching result
        for vote, result in votes:
            if vote == winner:
                result.result["consensus_score"] = consensus_score
                result.processing_notes = (
                    f"Consensus: {count}/{len(models)} models agreed"
                )
                return result

        return valid_results[0]

    def _extract_vote_key(self, task_type: str, result: TaskResult) -> Any:
        """Extract the key field to vote on based on task type."""
        r = result.result

        if task_type == "classify_wrangle":
            return r.get("context")
        elif task_type == "classify_topic":
            return r.get("primary_topic")
        elif task_type == "rate_difficulty":
            # Round to nearest 2 for fuzzy matching
            diff = r.get("difficulty")
            if diff is not None:
                return round(diff / 2) * 2
        elif task_type == "estimate_complexity":
            return r.get("complexity")
        elif task_type == "detect_bugs":
            bugs = r.get("bugs", [])
            return tuple(sorted(b.get("type", "") for b in bugs))

        return None

    async def dispatch_batch(
        self,
        task_type: str,
        items: list[dict[str, Any]],
        concurrency: int = 5,
    ) -> BatchResult:
        """Process a batch of items with concurrency control."""
        semaphore = asyncio.Semaphore(concurrency)

        async def process_item(item: dict[str, Any]) -> TaskResult:
            async with semaphore:
                item_id = item.get("id", "")
                code = item.get("code", "")
                return await self.dispatch(
                    task_type,
                    {"code": code, **{k: v for k, v in item.items() if k not in ("id", "code")}},
                    task_id=item_id,
                )

        results = await asyncio.gather(*[process_item(item) for item in items])

        # Compute stats
        success_count = sum(1 for r in results if r.status == TaskStatus.SUCCESS)
        error_count = sum(1 for r in results if r.status == TaskStatus.ERROR)
        confidences = [r.confidence for r in results if r.status == TaskStatus.SUCCESS]
        avg_confidence = sum(confidences) / len(confidences) if confidences else 0.0

        return BatchResult(
            results=list(results),
            batch_stats={
                "total": len(results),
                "success": success_count,
                "error": error_count,
                "avg_confidence": round(avg_confidence, 3),
            },
        )

    def should_flag_for_review(self, result: TaskResult) -> bool:
        """Check if a result should be flagged for human review."""
        quality_config = self._config.get("quality", {})
        confidence_threshold = quality_config.get("flag_confidence_below", 0.6)
        consensus_threshold = quality_config.get("flag_consensus_below", 0.66)

        # Low confidence
        if result.confidence < confidence_threshold:
            return True

        # Consensus failure
        consensus_score = result.result.get("consensus_score", 1.0)
        if consensus_score < consensus_threshold:
            return True

        # Error or uncertain status
        if result.status in (TaskStatus.ERROR, TaskStatus.UNCERTAIN):
            return True

        return False

    async def process_with_review(
        self,
        task_type: str,
        items: list[dict[str, Any]],
        concurrency: int = 5,
    ) -> tuple[list[TaskResult], list[TaskResult]]:
        """Process batch and separate results into passed and flagged."""
        batch_result = await self.dispatch_batch(task_type, items, concurrency)

        passed = []
        flagged = []

        for result in batch_result.results:
            if self.should_flag_for_review(result):
                flagged.append(result)
            else:
                passed.append(result)

        return passed, flagged

