tl = sorted(topics.keys())
pd = []
for i, t1 in enumerate(tl):
    for t2 in tl[i+1:]:
        n1 = t1.lower().replace('_', ' ').strip()
        n2 = t2.lower().replace('_', ' ').strip()
        if n1 == n2 or n1+'s' == n2 or n2+'s' == n1:
            pd.append((t1, t2))
if pd:
    print('Potential duplicate topics:')
    for t1,t2 in pd: print(f'  {repr(t1)} ({topics[t1]}) vs {repr(t2)} ({topics[t2]})')
else:
    print('No obvious duplicate topics.')

tc = []
for c in chunks:
    t = c.get('llm_topic')
    is_pc = False
    if isinstance(t, str) and t == 'point_cloud_ops': is_pc = True
    if isinstance(t, list) and 'point_cloud_ops' in t: is_pc = True
    if is_pc:
        ct = ''
        for cb in c.get('code_blocks', []): ct += cb.get('code', '')
        pfn = ['pcopen', 'pcfind', 'pcclose', 'pcfilter', 'pcimport', 'pcgenerate', 'pgfind', 'nearpoints']
        if not any(fn in ct.lower() for fn in pfn):
            tc.append((c['id'], ct[:80]))
if tc:
    print(f'point_cloud_ops but no pc* funcs: {len(tc)}')
    for cid, code in tc[:10]: print(f'  {cid}: code={repr(code)}')
    if len(tc) > 10: print(f'  ... and {len(tc)-10} more')
